aFA(a,b,c){var s=null,r=this.a,q=A.au(b,s,r,s,"bolag","bolag",s,s),p=""+a,o=A.au(a,s,r,s,p+" aff\xe4r",p+" aff\xe4rer",s,s)
return"Du har k\xf6pt "+A.v(c)+" "+q+" igen efter att allt s\xe5lts, "+o+" hittills."},
